INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 4, 'theory', 'Quiz: strings, structs and union');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 0, 'How many bytes does the string "hello" take in memory?', '["5", "6: five characters and the terminating zero", "4", "Depends on the platform"]', 1, 'A 0 byte is added at the end of every literal. So sizeof "hello" is 6, and strlen is 5; a buffer for a copy must be at least 6 bytes.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 1, 'What does strncpy(dst, src, n) do if src is longer than n?', '["Puts a zero at the end of dst", "Returns an error", "Truncates src in place", "Copies n bytes and does not write a terminating zero"]', 3, 'strncpy is not a “safe strcpy”: with no room for the zero, the string is left unterminated. snprintf(dst, sizeof dst, "%s", src) is more reliable.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 2, 'Why is sizeof(struct { char a; int b; char c; }) usually 12, not 6?', '["Fields are aligned, and padding is inserted between them and at the end", "The compiler adds an object header", "Strings always take 4 bytes each", "int takes 8 bytes"]', 0, 'An int must lie at an address divisible by 4; the struct as a whole is aligned to its strictest field. The order int, char, char gives 8.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 3, 'What happens when you write to one field of a union and read another?', '["A compilation error", "The value is zeroed", "The same bytes are read, interpreted as a different type", "The program crashes"]', 2, 'All fields of a union lie at one address. To know which field is “active”, you add a tag — that gives a tagged union.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 4, 4, 'Why can''t you write a struct to a file with fwrite(&s, sizeof s, 1, f) and read it on another machine?', '["fwrite cannot work with structs", "Structs are too large", "It always works", "The struct has padding with garbage, and byte order and alignment may differ"]', 3, 'The layout depends on the platform and compiler. For exchange, serialize the fields one at a time in an agreed byte order.');
